arguments.command:
python3 - <<'PY'
import sqlite3
p='incident/ledger.db'
db=sqlite3.connect(p)
for x in ['.schema','select * from balances','select * from payments','select * from postings',"select type,name,tbl_name,sql from sqlite_master where type in ('trigger','table','index') order by type,name"]:
 print('\n--',x)
 if x=='.schema':
  for r in db.execute("select sql from sqlite_master where sql is not null order by name"): print(r[0])
 else:
  try:
   for r in db.execute(x):print(r)
  except Exception as e: print(e)
PY
ls -l incident/ledger.db
cat incident/exit-code.txt

